import React from 'react';
import type { PublishPlatform } from '../../types/index';

/*
 * 平台标识。
 *
 * 来源与可信度**分开标注**，因为这三种情况的性质完全不同：
 *   - 'simple-icons'：官方品牌 SVG + 官方 hex，来自 simple-icons（CC0-1.0）。已核对 slug 与 hex。
 *   - 'brand-known'：抖音品牌红 #FE2C55 —— 与本项目强调色同源，可直接引用。
 *   - 'pending'：**没有**权威开源标识，用 monogram 顶位。
 *
 * ⚠️ 抖音**不能**用 simple-icons 的 `tiktok` 顶替：两者是同源但不同的品牌标识，
 *   混用等于用错商标（simple-icons 里确实没有 douyin 这个 slug）。
 * ⚠️ 微信系（公众号 / 视频号）用的是 WeChat 的官方绿，属近似；拿到官方素材后应替换。
 * ⚠️ 今日头条没有可验证的品牌色，故用中性墨色 monogram，等你们提供官方素材。
 */
type BrandSource = 'simple-icons' | 'brand-known' | 'pending';

interface Brand {
  label: string;
  color: string;
  monogram: string;
  source: BrandSource;
  path?: string;
}

