export const PLATFORM_BRAND: Record<PublishPlatform, Brand> = {
  douyin: { label: '抖音', color: '#FE2C55', monogram: '抖', source: 'brand-known' },
  xiaohongshu: { label: '小红书', color: '#FF2442', monogram: '红', source: 'simple-icons', path: XIAOHONGSHU_PATH },
  bilibili: { label: '哔哩哔哩', color: '#00A1D6', monogram: 'B', source: 'simple-icons', path: BILIBILI_PATH },
  toutiao: { label: '今日头条', color: '#98A2B3', monogram: '头', source: 'pending' },
  wechat_mp: { label: '微信公众号', color: '#07C160', monogram: '公', source: 'pending' },
  wechat_channels: { label: '微信视频号', color: '#07C160', monogram: '视', source: 'pending' },
};

/** 图标尺寸令牌（改造前全仓有 8 种散落的 size 值，没有令牌）。 */
const SIZE = { sm: 20, md: 24, lg: 28 } as const;

export interface PlatformLogoProps {
  platform: PublishPlatform;
  size?: keyof typeof SIZE;
  /** 是否显示平台名（默认只显示标识，名字由调用方决定放哪） */
  showLabel?: boolean;
  className?: string;
}

export function PlatformLogo({ platform, size = 'md', showLabel = false, className = '' }: PlatformLogoProps) {
  const brand = PLATFORM_BRAND[platform];
  const px = SIZE[size];
  /*
   * 真标识（simple-icons 的 path）与 monogram 需要不同的内边距：
   * 前者是按 24×24 画满整格设计的矢量字形 —— 缩到 62% 会糊成一团红点
   * （实测：小红书在 sm 尺寸下几乎认不出）；后者是文字，需要留白。
   */
  const mark = brand.path ? Math.round(px * 0.78) : Math.round(px * 0.56);

  return (
    <span className={`inline-flex items-center gap-2 ${className}`}>
      <span
        role="img"
        aria-label={brand.label}
        title={brand.source === 'pending' ? `${brand.label}（暂用字母标识，等官方素材）` : brand.label}
        className="inline-flex shrink-0 items-center justify-center rounded-md bg-well ring-1 ring-inset ring-line"
        style={{ width: px, height: px }}
      >
        {brand.path ? (
          <svg viewBox="0 0 24 24" width={mark} height={mark} fill={brand.color} aria-hidden="true">
            <path d={brand.path} />
          </svg>
        ) : (
          <span
            aria-hidden="true"
            className="font-display leading-none"
            style={{ color: brand.color, fontSize: mark }}
          >
            {brand.monogram}
          </span>
        )}
      </span>
      {showLabel && <span className="text-sm text-ink">{brand.label}</span>}
    </span>
  );
}

/** 渠道级标识：「其它平台」是视频号 + B站两个平台共用一个页签。 */
export function ChannelLogo({ platforms, size = 'md' }: { platforms: PublishPlatform[]; size?: keyof typeof SIZE }) {
  if (platforms.length <= 1) {
    return <PlatformLogo platform={platforms[0]!} size={size} />;
  }
  return (
    <span className="inline-flex items-center gap-1">
      {platforms.map((platform) => (
        <PlatformLogo key={platform} platform={platform} size={size} />
      ))}
    </span>
  );
}
